SELECT 'предложения по итогу сверки' t, match, COUNT(*) n FROM offers WHERE created_at >= datetime('now','-1 day') GROUP BY match ORDER BY n DESC;
WITH r AS (SELECT json_extract(j.value,'$.verdict') v FROM offers o, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL) SELECT 'требования по итогу' t, v, COUNT(*) n FROM r GROUP BY v ORDER BY n DESC;
WITH h AS (SELECT substr(url, instr(url,'://')+3) u, match_checks_json c FROM offers WHERE created_at >= datetime('now','-1 day') AND match_checks_json IS NOT NULL AND url LIKE 'http%'), r AS (SELECT substr(u,1,instr(u||'/','/')-1) host, json_extract(j.value,'$.verdict') v FROM h, json_each(h.c,'$.rows') j) SELECT 'сайты: не прочитано' t, host, COUNT(*) req_total, SUM(v='unknown') unk, ROUND(100.0*SUM(v='unknown')/COUNT(*)) unk_pct, SUM(v='yes') yes_, SUM(v='no') no_ FROM r GROUP BY host HAVING req_total >= 30 ORDER BY unk DESC LIMIT 30;
WITH r AS (SELECT substr(json_extract(j.value,'$.name'),1,50) req, json_extract(j.value,'$.verdict') v FROM offers o, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL) SELECT 'требования: чаще не прочитаны' t, req, SUM(v='unknown') unk, SUM(v='yes') yes_, SUM(v='no') no_ FROM r GROUP BY req HAVING unk >= 10 ORDER BY unk DESC LIMIT 40;
WITH r AS (SELECT substr(json_extract(j.value,'$.name'),1,50) req, json_extract(j.value,'$.verdict') v, json_extract(j.value,'$.found') f FROM offers o JOIN tender_items i ON i.id = o.item_id, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL AND (i.name LIKE '%ккумулятор%' OR i.name LIKE '%атарей%' OR i.name LIKE '%лемент питания%')) SELECT 'аккумуляторы и батарейки' t, req, SUM(v='unknown') unk, SUM(v='yes') yes_, SUM(v='no') no_, substr(MAX(CASE WHEN v='no' THEN f END),1,40) found_no FROM r GROUP BY req ORDER BY unk+no_ DESC LIMIT 25;
WITH r AS (SELECT substr(json_extract(j.value,'$.name'),1,50) req, json_extract(j.value,'$.verdict') v FROM offers o JOIN tender_items i ON i.id = o.item_id, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL AND (i.name LIKE '%ахил%' OR i.name LIKE '%ерчатк%' OR i.name LIKE '%приц%' OR i.name LIKE '%аск%' OR i.name LIKE '%гл%' OR i.name LIKE '%атетер%' OR i.name LIKE '%инт%')) SELECT 'медицина' t, req, SUM(v='unknown') unk, SUM(v='yes') yes_, SUM(v='no') no_ FROM r GROUP BY req ORDER BY unk+no_ DESC LIMIT 25;
WITH r AS (SELECT substr(json_extract(j.value,'$.name'),1,50) req, json_extract(j.value,'$.verdict') v FROM offers o JOIN tender_items i ON i.id = o.item_id, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL AND (i.name LIKE '%тол%' OR i.name LIKE '%тул%' OR i.name LIKE '%кресл%' OR i.name LIKE '%шкаф%' OR i.name LIKE '%Шкаф%')) SELECT 'мебель' t, req, SUM(v='unknown') unk, SUM(v='yes') yes_, SUM(v='no') no_ FROM r GROUP BY req ORDER BY unk+no_ DESC LIMIT 20;
WITH o2 AS (SELECT o.id, o.match, (SELECT COUNT(*) FROM json_each(o.match_checks_json,'$.rows') j WHERE json_extract(j.value,'$.verdict')='unknown') unk, (SELECT COUNT(*) FROM json_each(o.match_checks_json,'$.rows') j WHERE json_extract(j.value,'$.verdict')='no') no_ FROM offers o WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL) SELECT 'почти подошли: не хватает 1-2 пунктов' t, match, SUM(unk+no_ BETWEEN 1 AND 2) almost, SUM(unk+no_ >= 3) far, COUNT(*) total FROM o2 GROUP BY match;
WITH r AS (SELECT substr(o.url, instr(o.url,'://')+3) u, json_extract(j.value,'$.found') f FROM offers o, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL) SELECT 'мусор в значениях' t, substr(u,1,instr(u||'/','/')-1) host, SUM(f LIKE '%&nbsp%') nbsp, SUM(f IN ('0','0.0','0.000','0,000')) zero, SUM(f LIKE '%&quot%' OR f LIKE '%&amp%') ent FROM r GROUP BY host HAVING nbsp+zero+ent > 0 ORDER BY nbsp+zero+ent DESC LIMIT 15;
WITH r AS (SELECT json_extract(j.value,'$.name') req FROM offers o, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL) SELECT 'требования без названия' t, COUNT(*) n FROM r WHERE req IS NULL OR trim(req) IN ('','-','—');
WITH h AS (SELECT o.url, substr(o.url, instr(o.url,'://')+3) u, o.match_checks_json c, o.title FROM offers o WHERE o.created_at >= datetime('now','-1 day') AND o.match_checks_json IS NOT NULL AND o.url LIKE 'http%'), s AS (SELECT substr(u,1,instr(u||'/','/')-1) host, url, title, (SELECT group_concat(substr(json_extract(j.value,'$.name'),1,25), ', ') FROM json_each(c,'$.rows') j WHERE json_extract(j.value,'$.verdict')='unknown') unk_list, ROW_NUMBER() OVER (PARTITION BY substr(u,1,instr(u||'/','/')-1) ORDER BY length(c) DESC) rn FROM h) SELECT 'образцы страниц для правил чтения' t, host, substr(url,1,110) url, substr(title,1,50) title, substr(unk_list,1,160) unknown FROM s WHERE rn <= 3 AND host IN ('www.chipdip.ru','www.dealmed.ru','www.etm.ru','www.avtoall.ru','www.autoopt.ru','medrt.ru','www.sigma-med.ru','dezkont.ru','www.bigtv.ru','www.minimaks.ru','arselan.ru','bestkanc.ru') ORDER BY host;
SELECT 'уроки за сутки' t, agent, code, scope, count, substr(title,1,70) title FROM agents_lessons WHERE last_at >= datetime('now','-1 day') ORDER BY count DESC LIMIT 25;
SELECT 'агенты: задачи управляющего' t, whom, SUM(status='done') done, SUM(status='open') open_, SUM(status NOT IN ('done','open')) other, SUM(status='open' AND deadline < datetime('now')) overdue FROM agent_tasks WHERE created_at >= datetime('now','-14 day') GROUP BY whom ORDER BY open_ DESC;
SELECT 'агенты: кто нашёл ошибку (сам/проверяющий/человек)' t, agent, source, COUNT(*) kinds, SUM(count) times FROM agents_lessons GROUP BY agent, source ORDER BY agent, times DESC;
SELECT 'агенты: прогоны за 14 дней' t, agent, COUNT(*) runs, SUM(status='error') err, ROUND(AVG((julianday(finished_at)-julianday(started_at))*1440),1) avg_min FROM agents_runs WHERE started_at >= datetime('now','-14 day') GROUP BY agent;
SELECT 'знак и страна: согласие человека с агентом' t, kind, SUM(agree) agree, COUNT(*) total FROM marks_verdicts GROUP BY kind
